package com.xinhe.nexus.management.service;

import com.xinhe.nexus.management.auth.ManagementUser;
import java.math.BigDecimal;
import java.sql.Statement;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class ErpReturnService {
    private final JdbcTemplate db;
    public ErpReturnService(JdbcTemplate db){this.db=db;}
    public List<Map<String,Object>> returns(ManagementUser u,String returnNo,String orderNo,String status){require(u,"erp:sales-return:view");StringBuilder sql=new StringBuilder("SELECT r.id,r.return_no returnNo,o.order_no orderNo,o.customer_name_snapshot customerName,r.status,r.reason,r.created_at createdAt,r.received_at receivedAt,SUM(l.amount) returnAmount FROM erp_sales_return r JOIN erp_sales_fulfillment_order o ON o.id=r.order_id AND o.company_id=r.company_id JOIN erp_sales_return_line l ON l.return_id=r.id AND l.company_id=r.company_id WHERE r.company_id=?");java.util.ArrayList<Object>a=new java.util.ArrayList<>();a.add(u.companyId());like(sql,a,"r.return_no",returnNo);like(sql,a,"o.order_no",orderNo);if(status!=null&&!status.isBlank()){sql.append(" AND r.status=?");a.add(status.trim());}sql.append(" GROUP BY r.id,o.order_no,o.customer_name_snapshot ORDER BY r.id DESC");return db.queryForList(sql.toString(),a.toArray());}
    public Map<String,Object> detail(ManagementUser u,long id){require(u,"erp:sales-return:view");List<Map<String,Object>> rows=db.queryForList("SELECT r.id,r.return_no returnNo,r.order_id orderId,o.order_no orderNo,o.customer_name_snapshot customerName,r.status,r.reason,r.approval_opinion approvalOpinion,r.approved_at approvedAt,r.received_at receivedAt,r.version FROM erp_sales_return r JOIN erp_sales_fulfillment_order o ON o.id=r.order_id AND o.company_id=r.company_id WHERE r.company_id=? AND r.id=?",u.companyId(),id);if(rows.isEmpty())throw new ManagementException(HttpStatus.NOT_FOUND,"退货单不存在");Map<String,Object> result=rows.get(0);result.put("lines",db.queryForList("SELECT l.id,l.order_line_id orderLineId,l.product_id productId,f.product_code_snapshot productCode,f.product_name_snapshot productName,w.warehouse_name warehouseName,l.quantity,l.amount FROM erp_sales_return_line l JOIN erp_sales_fulfillment_line f ON f.id=l.order_line_id AND f.company_id=l.company_id JOIN erp_warehouse w ON w.id=l.warehouse_id AND w.company_id=l.company_id WHERE l.company_id=? AND l.return_id=? ORDER BY l.id",u.companyId(),id));return result;}
    @Transactional public Map<String,Object> create(ManagementUser u,ReturnInput in){require(u,"erp:sales-return:create");List<Map<String,Object>> orders=db.queryForList("SELECT fulfillment_status fulfillmentStatus FROM erp_sales_fulfillment_order WHERE company_id=? AND id=? FOR UPDATE",u.companyId(),in.orderId());if(orders.isEmpty()||!Set.of("DISPATCHED","SIGNED","COMPLETED","RETURNED").contains(orders.get(0).get("fulfillmentStatus")))throw bad("只有已出库发货的订单可以退货");if(in.lines()==null||in.lines().isEmpty())throw bad("请至少选择一个退货商品");String no="SR-"+String.format("%08d",nextNumber(u.companyId(),"SALES_RETURN"));long id=insert("INSERT INTO erp_sales_return(company_id,order_id,return_no,reason,created_by) VALUES(?,?,?,?,?)",u.companyId(),in.orderId(),no,required(in.reason(),"退货原因"),u.id());Set<Long> seen=new HashSet<>();for(ReturnLineInput input:in.lines()){if(input.quantity()==null||input.quantity()<=0||!seen.add(input.orderLineId()))throw bad("退货商品或数量无效");List<Map<String,Object>> lines=db.queryForList("SELECT f.product_id productId,f.quantity,f.unit_price unitPrice,d.warehouse_id warehouseId FROM erp_sales_fulfillment_line f JOIN erp_sales_dispatch_line dl ON dl.company_id=f.company_id AND dl.order_line_id=f.id JOIN erp_sales_dispatch d ON d.id=dl.dispatch_id AND d.company_id=dl.company_id WHERE f.company_id=? AND f.order_id=? AND f.id=?",u.companyId(),in.orderId(),input.orderLineId());if(lines.isEmpty())throw bad("退货商品不属于该订单或尚未出库");Map<String,Object> line=lines.get(0);Long used=db.queryForObject("SELECT COALESCE(SUM(l.quantity),0) FROM erp_sales_return_line l JOIN erp_sales_return r ON r.id=l.return_id AND r.company_id=l.company_id WHERE l.company_id=? AND l.order_line_id=? AND r.status<>'REJECTED'",Long.class,u.companyId(),input.orderLineId());long ordered=((Number)line.get("quantity")).longValue();if(input.quantity()+(used==null?0:used)>ordered)throw bad("累计退货数量不能超过原订单数量");BigDecimal amount=((BigDecimal)line.get("unitPrice")).multiply(BigDecimal.valueOf(input.quantity())).setScale(2);db.update("INSERT INTO erp_sales_return_line(company_id,return_id,order_line_id,warehouse_id,product_id,quantity,amount) VALUES(?,?,?,?,?,?,?)",u.companyId(),id,input.orderLineId(),line.get("warehouseId"),line.get("productId"),input.quantity(),amount);}db.update("UPDATE erp_sales_fulfillment_order SET fulfillment_status='RETURNING',version=version+1,updated_by=? WHERE company_id=? AND id=?",u.id(),u.companyId(),in.orderId());return Map.of("id",id,"returnNo",no,"status","PENDING_APPROVAL");}
    @Transactional public void decide(ManagementUser u,long id,boolean approve,String opinion){require(u,"erp:sales-return:approve");int n=db.update("UPDATE erp_sales_return SET status=?,approval_opinion=?,approved_by=?,approved_at=NOW(),version=version+1 WHERE company_id=? AND id=? AND status='PENDING_APPROVAL'",approve?"APPROVED":"REJECTED",trim(opinion),u.id(),u.companyId(),id);if(n!=1)throw bad("退货单不在待审核状态");if(!approve){Long orderId=db.queryForObject("SELECT order_id FROM erp_sales_return WHERE company_id=? AND id=?",Long.class,u.companyId(),id);db.update("UPDATE erp_sales_fulfillment_order SET fulfillment_status='COMPLETED',version=version+1,updated_by=? WHERE company_id=? AND id=? AND fulfillment_status='RETURNING'",u.id(),u.companyId(),orderId);}}
    @Transactional public void receive(ManagementUser u,long id){require(u,"erp:sales-return:receive");List<Map<String,Object>> returns=db.queryForList("SELECT order_id orderId FROM erp_sales_return WHERE company_id=? AND id=? AND status='APPROVED' FOR UPDATE",u.companyId(),id);if(returns.isEmpty())throw bad("只有审核通过的退货单可以收货");for(Map<String,Object> line:db.queryForList("SELECT warehouse_id warehouseId,product_id productId,quantity FROM erp_sales_return_line WHERE company_id=? AND return_id=?",u.companyId(),id)){long warehouse=((Number)line.get("warehouseId")).longValue(),product=((Number)line.get("productId")).longValue(),qty=((Number)line.get("quantity")).longValue();db.update("INSERT INTO erp_inventory_balance(company_id,warehouse_id,product_id,quantity) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity),version=version+1",u.companyId(),warehouse,product,qty);Long after=db.queryForObject("SELECT quantity FROM erp_inventory_balance WHERE company_id=? AND warehouse_id=? AND product_id=?",Long.class,u.companyId(),warehouse,product);db.update("INSERT INTO erp_inventory_transaction(company_id,warehouse_id,product_id,transaction_type,quantity_change,balance_after,source_type,source_id,reason,operated_by) VALUES(?,?,?,'SALES_RETURN',?,?,'SALES_RETURN',?,'销售退货收货',?)",u.companyId(),warehouse,product,qty,after,id,u.id());}db.update("UPDATE erp_sales_return SET status='RECEIVED',received_by=?,received_at=NOW(),version=version+1 WHERE company_id=? AND id=?",u.id(),u.companyId(),id);db.update("UPDATE erp_sales_fulfillment_order SET fulfillment_status='RETURNED',version=version+1,updated_by=? WHERE company_id=? AND id=?",u.id(),u.companyId(),returns.get(0).get("orderId"));}
    public List<Map<String,Object>> report(ManagementUser u,String dimension){require(u,"erp:sales-report:view");return switch(dimension==null?"customer":dimension){case "salesperson"->db.queryForList("SELECT o.salesperson_user_id dimensionId,u.display_name dimensionName,COUNT(DISTINCT o.id) orderCount,SUM(l.amount) salesAmount,COALESCE((SELECT SUM(rl.amount) FROM erp_sales_return_line rl JOIN erp_sales_return r ON r.id=rl.return_id AND r.company_id=rl.company_id JOIN erp_sales_fulfillment_order ro ON ro.id=r.order_id AND ro.company_id=r.company_id WHERE r.company_id=o.company_id AND ro.salesperson_user_id=o.salesperson_user_id AND r.status='RECEIVED'),0) returnAmount FROM erp_sales_fulfillment_order o JOIN erp_sales_fulfillment_line l ON l.order_id=o.id AND l.company_id=o.company_id JOIN sys_user u ON u.id=o.salesperson_user_id WHERE o.company_id=? GROUP BY o.salesperson_user_id,u.display_name",u.companyId());case "product"->db.queryForList("SELECT l.product_id dimensionId,l.product_code_snapshot productCode,l.product_name_snapshot dimensionName,SUM(l.quantity) salesQuantity,SUM(l.amount) salesAmount,COALESCE((SELECT SUM(rl.quantity) FROM erp_sales_return_line rl JOIN erp_sales_return r ON r.id=rl.return_id AND r.company_id=rl.company_id WHERE rl.company_id=l.company_id AND rl.product_id=l.product_id AND r.status='RECEIVED'),0) returnQuantity,COALESCE((SELECT SUM(rl.amount) FROM erp_sales_return_line rl JOIN erp_sales_return r ON r.id=rl.return_id AND r.company_id=rl.company_id WHERE rl.company_id=l.company_id AND rl.product_id=l.product_id AND r.status='RECEIVED'),0) returnAmount FROM erp_sales_fulfillment_line l JOIN erp_sales_fulfillment_order o ON o.id=l.order_id AND o.company_id=l.company_id WHERE l.company_id=? GROUP BY l.product_id,l.product_code_snapshot,l.product_name_snapshot",u.companyId());default->db.queryForList("SELECT o.customer_id dimensionId,o.customer_name_snapshot dimensionName,COUNT(DISTINCT o.id) orderCount,SUM(l.amount) salesAmount,COALESCE((SELECT SUM(rl.amount) FROM erp_sales_return_line rl JOIN erp_sales_return r ON r.id=rl.return_id AND r.company_id=rl.company_id JOIN erp_sales_fulfillment_order ro ON ro.id=r.order_id AND ro.company_id=r.company_id WHERE r.company_id=o.company_id AND ro.customer_id=o.customer_id AND r.status='RECEIVED'),0) returnAmount FROM erp_sales_fulfillment_order o JOIN erp_sales_fulfillment_line l ON l.order_id=o.id AND l.company_id=o.company_id WHERE o.company_id=? GROUP BY o.customer_id,o.customer_name_snapshot",u.companyId());};}
    private long insert(String sql,Object...args){GeneratedKeyHolder key=new GeneratedKeyHolder();db.update(c->{var ps=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS);for(int i=0;i<args.length;i++)ps.setObject(i+1,args[i]);return ps;},key);return key.getKey().longValue();}private long nextNumber(long c,String t){db.update("INSERT INTO erp_number_sequence(company_id,document_type,current_value) VALUES(?,?,1) ON DUPLICATE KEY UPDATE current_value=current_value+1",c,t);return db.queryForObject("SELECT current_value FROM erp_number_sequence WHERE company_id=? AND document_type=?",Long.class,c,t);}private void like(StringBuilder s,List<Object>a,String c,String v){if(v!=null&&!v.isBlank()){s.append(" AND ").append(c).append(" LIKE CONCAT('%',?,'%')");a.add(v.trim());}}private boolean admin(ManagementUser u){return u.roles().contains("COMPANY_ADMIN")||u.roles().contains("PLATFORM_ADMIN")||u.permissions().contains("*");}private void require(ManagementUser u,String p){if(u.companyId()==null)throw new ManagementException(HttpStatus.FORBIDDEN,"账号未关联公司");if(admin(u)||u.permissions().contains(p))return;throw new ManagementException(HttpStatus.FORBIDDEN,"没有执行该操作的权限");}private String required(String s,String l){if(s==null||s.isBlank())throw bad(l+"不能为空");return s.trim();}private String trim(String s){return s==null||s.isBlank()?null:s.trim();}private ManagementException bad(String m){return new ManagementException(HttpStatus.BAD_REQUEST,m);}
    public record ReturnInput(long orderId,String reason,List<ReturnLineInput> lines){}public record ReturnLineInput(long orderLineId,Long quantity){}public record Decision(String opinion){}
}
